from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class SolverProfile:
    method: str
    use_analytic_jacobian: bool


_STIFF_METHODS = ("LSODA", "BDF", "Radau")
_EXPLICIT_METHODS = ("RK45", "RK23", "DOP853")
_SUPPORTED_METHODS = _STIFF_METHODS + _EXPLICIT_METHODS


def _profile_for_method(method: str) -> SolverProfile:
    return SolverProfile(
        method=method,
        use_analytic_jacobian=method in _STIFF_METHODS,
    )


PROFILES = {
    "automatic_stiff": SolverProfile(
        method="LSODA",
        use_analytic_jacobian=True,
    )
}
PROFILES.update(
    {method: _profile_for_method(method) for method in _SUPPORTED_METHODS}
)


def resolve_solver_profile(name: str) -> SolverProfile:
    normalized = name.strip().lower()
    for key, profile in PROFILES.items():
        if key.lower() == normalized:
            return profile
    raise ValueError(f"unknown solver profile: {name}")

